const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export function photoRate(light,co2,temperature=25){return Math.round(clamp(light/70,0,1)*clamp(co2/65,0,1)*Math.exp(-(((temperature-25)/22)**2))*100)}
export function osmosisModel(concentration){const difference=clamp(concentration,0,100)-50;return {mode:difference>3?'Ưu trương':difference< -3?'Nhược trương':'Gần đẳng trương',scale:clamp(.92-difference*.006,.55,.98),direction:difference>3?'out':difference< -3?'in':'balanced',index:Math.round(clamp(100-difference*.8,60,140))}}
export function enzymeRate(temperature,ph){return temperature>=65?0:Math.round(clamp(Math.exp(-(((temperature-35)/19)**2))*Math.exp(-(((ph-7)/2.2)**2)),0,1)*100)}
export function energyLevels(initial,efficiency){return Array.from({length:4},(_,i)=>Number((initial*(efficiency/100)**i).toFixed(2)))}
export function punnett(parentA,parentB){if(!['AA','Aa','aa'].includes(parentA)||!['AA','Aa','aa'].includes(parentB))throw new Error('Invalid genotype');const cells=[];for(const b of parentB)for(const a of parentA)cells.push([a,b].sort().join(''));const counts={AA:0,Aa:0,aa:0};for(const x of cells)counts[x]++;return {cells,counts,dominant:(counts.AA+counts.Aa)/4,recessive:counts.aa/4}}
export function sampleOffspring(parentA,parentB,size=20,random=Math.random){const {cells}=punnett(parentA,parentB),counts={AA:0,Aa:0,aa:0},offspring=[];for(let i=0;i<size;i++){const item=cells[Math.min(3,Math.floor(random()*4))];counts[item]++;offspring.push(item)}return {counts,offspring}}
